(() => {
  const all = document.querySelectorAll('*');
  for (const el of all) {
    if (el.children.length === 0 && el.textContent.trim() === 'river-flash-2143') {
      el.setAttribute('data-std-model', 'true');
      const r = el.getBoundingClientRect();
      return { selector: '[data-std-model="true"]', x: r.x, y: r.y, w: r.width, h: r.height };
    }
  }
  return null;
})()
